package com.johnny.hotel.damage;
import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component@RequiredArgsConstructor public class DamageAccess{private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String> roles){}
 public Actor actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getDetails() instanceof Long id))throw denied();var u=users.selectById(id);var rs=roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());if(u==null||!Integer.valueOf(1).equals(u.getStatus())||rs.contains("HR_ADMIN")||rs.contains("CUSTOMER"))throw denied();return new Actor(id,rs);}
 public void read(Actor a){require(a,Set.of("STAFF","FINANCE","MANAGER","OWNER","SUPER_ADMIN"));}public void report(Actor a){require(a,Set.of("STAFF","MANAGER","OWNER","SUPER_ADMIN"));}public void assess(Actor a){require(a,Set.of("FINANCE","MANAGER","OWNER","SUPER_ADMIN"));}private void require(Actor a,Set<String> allowed){if(a.roles().stream().noneMatch(allowed::contains))throw denied();}public AccessDeniedException denied(){return new AccessDeniedException("Damage assessment access denied");}}
